from collections import defaultdict

np10 = []
for line in demo_input_str.strip().split('\n'):
    np10.append([int(x) for x in line.split()])

def find_regions(grid, val):
    """Find all connected regions of a value"""
    regions = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == val and (r, c) not in visited:
                # BFS to find connected region
                region = []
                stack = [(r, c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    region.append((curr_r, curr_c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == val and (nr, nc) not in visited:
                                stack.append((nr, nc))
                regions.append(region)
    return regions

print("Connected regions for each special value:")
for val in sorted([v for v in set(val for row in np10 for val in row) if val not in [0, 5]]):
    regions = find_regions(np10, val)
    print(f"\nVal {val}: {len(regions)} region(s)")
